def list_named_queries(self, workgroup: Optional[str] = None) -> Dict[str, List[str]]:
    """
    List named queries, optionally filtered by workgroup.
    """
    if workgroup is not None:
        return {
            "NamedQueryIds": [
                query.id
                for query in self.named_queries.values()
                if query.workgroup and query.workgroup.name == workgroup
            ]
        }
    return {"NamedQueryIds": []}

def create_prepared_statement(
    self,
    statement_name: str,
    workgroup: str,
    query_statement: str,
    description: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Create a prepared statement.
    """
    if workgroup not in self.work_groups:
        raise ValueError(f"WorkGroup {workgroup} does not exist")

    if workgroup not in self.prepared_statements:
        self.prepared_statements[workgroup] = {}

    prepared_statement = PreparedStatement(
        statement_name=statement_name,
        query_statement=query_statement,
        workgroup=self.work_groups[workgroup],
        description=description,
    )

    self.prepared_statements[workgroup][statement_name] = prepared_statement

    return {
        "ResponseMetadata": {
            "RequestId": str(mock_random.uuid4()),
            "HTTPStatusCode": 200,
            "HTTPHeaders": {
                "server": "amazon.com",
                "date": datetime.datetime.now().strftime("%a, %d %b %Y %H:%M:%S GMT"),
                "x-amzn-requestid": str(mock_random.uuid4()),
            },
            "RetryAttempts": 0,
        }
    }

def get_prepared_statement(
    self, statement_name: str, workgroup: str
) -> Dict[str, Any]:
    """
    Get a prepared statement.
    """
    if workgroup not in self.prepared_statements or statement_name not in self.prepared_statements[workgroup]:
        raise ValueError(f"Prepared statement {statement_name} does not exist in workgroup {workgroup}")

    statement = self.prepared_statements[workgroup][statement_name]

    return {
        "PreparedStatement": {
            "StatementName": statement.statement_name,
            "QueryStatement": statement.query_statement,
            "WorkGroupName": workgroup,
            "Description": statement.description,
            "LastModifiedTime": statement.last_modified_time.timestamp(),
        }
    }

